q11 = if(equal(old, 0), 1, if(equal(old, 1), 1, if(equal(old, 2), 1, if(equal(old, 3), 2, if(equal(old, 4), 1, if(equal(old, 5), 2, if(equal(old, 6), 3, 3)))))));
