 float ey1_a = mix(cos(q12 * 3.14159265 * (p.x)) * cos(q11 * 3.14159265 * (p.y + h)) + q13 * cos(q11 * 3.14159265 * (p.x)) * cos(q12 * 3.14159265 * (p.y + h)), cos(q15 * 3.14159265 * (p.x)) * cos(q14 * 3.14159265 * (p.y + h)) + q16 * cos(q14 * 3.14159265 * (p.x)) * cos(q15 * 3.14159265 * (p.y + h)), q17);
