 vec3 b = GetBlur1(src);
 float u = m.x / 0.45 * (1.0 + clamp(k * lap, -0.06, 0.06));
 u = mix(u, b.x / 0.45, clamp(e0 * q18 * 0.08, 0.0, 0.35));
 float local_mean = max(GetBlur3(src).x / 0.45, 0.02);
 u *= pow(0.3 / local_mean, 0.04);
